class Tracker
{
public:
    explicit Tracker(int& alive) : m_alive{ alive }
    {
        ++m_alive;
    }

    ~Tracker()
    {
        --m_alive;
    }

private:
    int& m_alive;
};

unitTests:
TEST("alive only inside its scope") {
    int alive{ 0 };
    {
        Tracker a{ alive };
        CHECK_EQ(alive, 1);
        {
            Tracker b{ alive };
            Tracker c{ alive };
            CHECK_EQ(alive, 3);
        }
        CHECK_EQ(alive, 1);
    }
    CHECK_EQ(alive, 0);
}
TEST("a temporary dies at the end of its statement") { int alive{ 0 }; Tracker{ alive }; CHECK_EQ(alive, 0); }

